 function tools(holdings=false){return `<div class="asset-toolbar"><label class="asset-search">${icon('search',17)}<input id="asset-search" aria-label="搜索资产记录" value="${esc(search)}" placeholder="搜索名称、代码或备注…"></label>${holdings?`<select id="asset-category" aria-label="按资产类别筛选"><option value="all">全部类别</option>${Object.entries(ASSET_CATEGORIES).map(([v,l])=>`<option value="${v}" ${category===v?'selected':''}>${l}</option>`).join('')}</select><select id="asset-account" aria-label="按账户筛选"><option value="all">全部账户</option>${all('asset_account').map(x=>`<option value="${esc(x.id)}" ${account===x.id?'selected':''}>${esc(x.title)}</option>`).join('')}</select>`:''}</div>`;}
 function row(x){const type=x.kind==='asset_holding'?ASSET_CATEGORIES[x.category]||'其他资产':kindName(x.kind);return `<article class="asset-record"><button class="asset-record-main" data-action="asset-detail:${esc(x.id)}"><span class="asset-record-icon">${icon(x.kind==='asset_liability'?'task':x.kind==='asset_account'?'grid':'activity',20)}</span><span class="asset-record-copy"><strong>${esc(x.title)}</strong><small>${esc(type)}${x.accountId?' · '+esc(accountName(x)):''}${status(x)?' · '+esc(status(x)):''}</small><small>${sourceLine(x)}</small></span><span class="asset-record-amount">${esc(amount(x))}<small>${currency(x)}${x.kind==='asset_holding'&&assetProfit(x)!==null?'<br>'+((x.note||'').includes('估算')?'按估算成本 ':'按账本成本 ')+esc(money(assetProfit(x),currency(x))):x.kind==='asset_holding'?'<br>成本待核实':''}</small></span>${icon('arrow',15)}</button></article>`;}
 function empty(text,kind){return `<div class="asset-empty">${icon('grid',28)}<h3>${text}</h3><p>先留下一条记录，来源和日期可以一起保存。</p>${kind?btn('添加'+kindName(kind),'asset-add:'+kind,'primary','plus'):''}</div>`;}
 function overview(){const totals=calculateAssetTotals(ctx.items),unknown=totals.reduce((n,g)=>n+g.unknown,0);return `<section class="asset-intro"><span class="asset-eyebrow">我的资产</span><h2>看清家底，安心安排。</h2><p>账户、投资与固定资产，放在一处；金额按原币种和记录日期展示。</p></section><div class="asset-total-grid">${totals.length?totals.map(g=>`<section class="card asset-total"><div class="asset-total-head"><span>${esc(g.currency)} · ${g.unknownLiabilities?'已知资产估值':'已估值净额'}</span>${icon('grid',19)}</div><strong>${money(g.unknownLiabilities?g.assets:g.net,g.currency)}</strong><dl><div><dt>已记录资产</dt><dd>${money(g.assets,g.currency)}</dd></div><div><dt>已记录负债</dt><dd>${g.unknownLiabilities?'待核实（'+g.unknownLiabilities+'项）':money(g.liabilities,g.currency)}</dd></div></dl><small>${g.dates.length?`${g.dates[0]}${g.dates.length>1?' 至 '+g.dates.at(-1):''} · 来源快照，非实时估值`:'估值日期待补'}${g.unknown?` · ${g.unknown} 项未估值，未计入`:''}${g.pendingCount?` · 待核对估值 ${money(g.pendingValue,g.currency)}（${g.pendingCount}项，未计入）${g.pendingUnvalued?'，其中'+g.pendingUnvalued+'项金额未知':''}`:''}</small></section>`).join(''):`<section class="card asset-total"><span>从第一笔资产开始</span><strong>尚无估值</strong><p>没有填写金额的资产会保留，不会当作零元。</p></section>`}</div><div class="asset-quick">${[['asset_account','添加账户','grid'],['asset_holding','添加资产','plus'],['asset_transaction','记一笔流水','file'],['asset_liability','记录负债','task']].map(([k,l,i])=>btn(l,'asset-add:'+k,'',i)).join('')}</div><p class="asset-accounting-note">按币种分别统计，不自动换汇；账户余额只有明确勾选计入时才加总。流水仅留档，不重复改变持仓。${unknown?'尚有未估值或待核对项目。':''}</p><div class="asset-overview-grid"><section class="card"><div class="card-head"><h2 class="card-title">资产构成</h2>${btn('全部资产','nav:holdings')}</div><div class="asset-allocation">${totals.filter(g=>g.assets>0&&Object.keys(g.categories).length).map(g=>`<h3>${esc(g.currency)}</h3>${Object.entries(g.categories).map(([k,v])=>`<div class="asset-allocation-row"><span>${esc(ASSET_CATEGORIES[k]||k)}</span><strong>${money(v,g.currency)}</strong><div><i style="width:${Math.max(0,Math.min(100,v/g.assets*100)).toFixed(2)}%"></i></div></div>`).join('')}`).join('')||'<p class="asset-muted">有估值的资产会在这里按类别展示。</p>'}</div></section><section class="card"><div class="card-head"><h2 class="card-title">最近流水</h2>${btn('全部流水','nav:transactions')}</div>${all('asset_transaction').sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5).map(row).join('')||empty('还没有流水记录','asset_transaction')}</section></div><section class="card"><div class="card-head"><h2 class="card-title">账户 <span class="subtitle">${all('asset_account').length} 个</span></h2>${btn('查看账户','nav:accounts')}</div>${all('asset_account').slice(0,4).map(row).join('')||empty('把常用账户加进来','asset_account')}</section>`;}
 function documents(){const files=filtered(all('file'));return `${tools()}<section class="card"><div class="card-head"><h2 class="card-title">资料原件 <span class="subtitle">${files.length} 份</span></h2>${btn('上传资料','asset-upload','primary','plus')}</div><p class="asset-pad asset-muted">保存账单、证明和导入原始文件。点击缩略图或名称查看原件。</p>${files.map(f=>`<article class="asset-document">${ctx.previews?.thumb(f,'asset-preview:'+f.id)||icon('file',24)}<div><button class="link-title" data-action="asset-preview:${esc(f.id)}">${esc(f.title)}</button><small>${esc(f.date)} · ${Math.ceil((f.size||0)/1024)}KB</small>${f.note?`<p>${esc(f.note)}</p>`:''}</div><button class="icon-btn" data-action="asset-delete:${esc(f.id)}" aria-label="删除${esc(f.title)}">${icon('trash',16)}</button></article>`).join('')||empty('还没有资料原件')}</section>`;}
 function records(p){const kind={accounts:'asset_account',holdings:'asset_holding',transactions:'asset_transaction',liabilities:'asset_liability',history:'asset_snapshot'}[p],list=filtered(all(kind)).sort((a,b)=>b.date.localeCompare(a.date));return `${tools(p==='holdings')}<section class="card"><div class="card-head"><h2 class="card-title">${ASSET_PAGES[p]} <span class="subtitle">${list.length} 条</span></h2>${btn('添加'+kindName(kind),'asset-add:'+kind,'primary','plus')}</div>${p==='history'?'<p class="asset-pad asset-muted">历史快照单独保存，不计入当前资产总额。</p>':''}<div id="asset-record-list">${list.map(row).join('')||empty('还没有'+ASSET_PAGES[p],kind)}</div></section>`;}
 function render(){const key=[ctx.workbench,ctx.space,ctx.account?.user?.id||'',ctx.page].join(':');if(location!==key){cleanup();location=key;}return `<div class="assets-content">${ctx.space==='demo'?'<div class="asset-demo">示例空间 · 所有数据均为虚构，与个人资产分别保存。</div>':''}${page()==='dashboard'?overview():page()==='documents'?documents():records(page())}</div>`;}
 function bind(){const input=document.querySelector('#asset-search');if(input)input.oninput=e=>{search=e.target.value;repaintList();};const cat=document.querySelector('#asset-category');if(cat)cat.onchange=e=>{category=e.target.value;repaintList();};const ac=document.querySelector('#asset-account');if(ac)ac.onchange=e=>{account=e.target.value;repaintList();};}
 function repaintList(){const list=document.querySelector('#asset-record-list'),kind={accounts:'asset_account',holdings:'asset_holding',transactions:'asset_transaction',liabilities:'asset_liability',history:'asset_snapshot'}[page()];if(list){const rows=filtered(all(kind));list.innerHTML=rows.map(row).join('')||empty('没有匹配的记录',kind);}else if(page()==='documents'){const box=document.querySelector('.assets-content');ctx.previews?.cleanupThumbs();if(box)box.innerHTML=documents();bind();ctx.previews?.mount();const el=document.querySelector('#asset-search');el?.focus();el?.setSelectionRange(search.length,search.length);}}
 function fields(kind,x){const num=(l,n,signed=false)=>field(l,n,x[n]??'','number',(signed?'':'min="0" ')+'step="any"');const cur=select('币种','currency',[['CNY','CNY 人民币'],['USD','USD 美元'],['HKD','HKD 港币'],['EUR','EUR 欧元'],['JPY','JPY 日元'],['GBP','GBP 英镑']],x.currency||'CNY');let html=cur;
  if(kind==='asset_account')html+=field('账户类型','accountType',x.accountType||'','text','maxlength="80" placeholder="银行 / 券商 / 支付账户"')+field('机构','institution',x.institution||'','text','maxlength="250"')+num('账户余额（可留空）','balance')+field('余额日期','balanceAsOf',x.balanceAsOf||x.date||ctx.today,'date')+`<label class="asset-check"><input type="checkbox" name="includeInTotal" ${x.includeInTotal?'checked':''}><span>将账户余额计入资产总额<small>只用于独立现金余额；若余额已包含下方持仓，请不要勾选。</small></span></label>`;
  if(kind==='asset_holding')html+=select('资产类别','category',Object.entries(ASSET_CATEGORIES),x.category||'other')+select('所属账户','accountId',options(),x.accountId||'')+`<div class="form-grid">${num('数量 / 份额（选填）','quantity')}${num('单价 / 净值（选填）','unitPrice')}</div>`+num('当前估值（选填）','value')+num('账本总成本（选填）','cost')+field('估值日期','valuationDate',x.valuationDate||x.date||ctx.today,'date')+select('状态','status',[['active','在用 / 持有'],['closed','已结束'],['pending','待核对']],x.status||'active')+'<p class="asset-muted">估值留空时，仅在数量和单价都已知时计算；没有可靠价格的固定资产保留为未估值。</p>';
  if(kind==='asset_liability')html+=num('未偿余额','balance')+select('关联账户','accountId',options(),x.accountId||'')+field('余额确认日期','asOfDate',x.asOfDate||x.date||ctx.today,'date')+field('到期日（选填）','dueDate',x.dueDate||'','date')+select('状态','status',[['active','尚未结清'],['closed','已结清'],['pending','待核对']],x.status||'active');
  if(kind==='asset_transaction')html+=num('流水金额（保留正负号）','amount',true)+select('流水类型','transactionType',[['income','收入'],['expense','支出'],['transfer','转账'],['buy','买入'],['sell','卖出'],['dividend','分红'],['fee','费用'],['repayment','还款'],['other','其他']],x.transactionType||'other')+select('关联账户','accountId',options(),x.accountId||'')+select('确认状态','status',[['confirmed','已确认发生'],['pending','待核对 / 计划']],x.status||'confirmed')+'<p class="asset-muted">这里只记录已发生或待核对的流水，不发起转账或投资交易，也不自动改动持仓。</p>';
  if(kind==='asset_snapshot')html+=num('快照净额（选填）','totalValue',true)+num('资产总额（选填）','assetValue')+num('负债总额（选填）','liabilityValue')+'<p class="asset-muted">历史估值仅留档，不重复计入当前资产总额。</p>';
  return html+`<details class="asset-source-fields"><summary>来源与编号（选填）</summary>${field('来源','source',x.source||'','text','maxlength="250"')}${field('来源日期','sourceDate',x.sourceDate||'','date')}${field('外部编号 / 代码','externalId',x.externalId||'','text','maxlength="250"')}</details>`;}
 function edit(kind,id){const x=find(id)||{date:ctx.today},sourceSpace=ctx.space,sourceWorkbench=ctx.workbench,owner=ctx.account?.user?.id;ctx.openDrawer(`<form id="asset-form"><div class="helper">${ctx.space==='demo'?'示例空间 · 虚构记录':'个人资产空间'}</div>${field('名称','title',x.title||'','text','required maxlength="120"')}${field('记录日期','date',x.date||ctx.today,'date','required')}${fields(kind,x)}<div class="field"><label for="asset-note">备注</label><textarea id="asset-note" name="note" maxlength="5000">${esc(x.note||'')}</textarea></div><div id="asset-error" role="alert"></div></form>`,`${id?'编辑':'添加'}${kindName(kind)}`,'金额按原币种保留，来源与日期一起记录',`${btn('取消','close')}<button form="asset-form" type="submit" class="btn primary">保存${kindName(kind)}</button>`);
  const form=document.querySelector('#asset-form');form.onsubmit=async e=>{e.preventDefault();if(ctx.space!==sourceSpace||ctx.workbench!==sourceWorkbench||ctx.account?.user?.id!==owner){ctx.toast('空间或账号已变化，请重新打开表单');return;}const button=document.querySelector('[form="asset-form"]');button.disabled=true;try{const data=Object.fromEntries(new FormData(form));for(const n of ['balance','quantity','unitPrice','cost','value','amount','totalValue','assetValue','liabilityValue'])if(n in data){if(data[n]==='')data[n]=null;else data[n]=Number(data[n]);}for(const n of ['accountId','dueDate','sourceDate','externalId','balanceAsOf','valuationDate','asOfDate'])if(data[n]==='')data[n]='';if(kind==='asset_account')data.includeInTotal=form.elements.includeInTotal.checked;await ctx.api(id?'/api/items/'+id:'/api/items',{method:id?'PUT':'POST',body:JSON.stringify({...data,kind})},sourceSpace,sourceWorkbench);if(form.isConnected)ctx.closeDrawer();await ctx.load();ctx.toast('资产记录已保存');}catch(error){if(form.isConnected)document.querySelector('#asset-error').innerHTML=`<div class="form-error">${esc(error.message)}</div>`;else ctx.toast(error.message);}finally{button.disabled=false;}};}
 function detail(id){const x=find(id);if(!x)return;const facts=[['金额 / 估值',amount(x)],['币种',currency(x)],['状态',status(x)||'按原记录'],['类别',ASSET_CATEGORIES[x.category]||x.accountType||x.transactionType||kindName(x.kind)],['账户',x.accountId?accountName(x):'未关联'],['记录日期',x.date],['估值 / 确认日期',x.valuationDate||x.balanceAsOf||x.asOfDate||x.sourceDate||'未注明'],['数量 / 份额',finite(x.quantity)?String(x.quantity):'未注明'],['单价 / 净值',finite(x.unitPrice)?String(x.unitPrice):'未注明'],['账本成本',finite(x.cost)?money(x.cost,currency(x)):'待核实'],['来源',x.source||'手工记录'],['外部编号',x.externalId||'未注明']];ctx.openDrawer(`<dl class="asset-detail-grid">${facts.map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl>${x.note?`<h3 class="clinical-label">备注与来源说明</h3><div class="report-text">${esc(x.note)}</div>`:''}${x.referenceUrl&&/^https:\/\//.test(x.referenceUrl)?`<a class="btn" href="${esc(x.referenceUrl)}" target="_blank" rel="noopener noreferrer">打开来源页面</a>`:''}`,esc(x.title),kindName(x.kind),`${btn('删除','asset-delete:'+id)}${btn('编辑','asset-edit:'+id,'primary','edit')}`);}
 function remove(id){const x=find(id);if(!x)return;pendingDelete={id,space:ctx.space,workbench:ctx.workbench,owner:ctx.account?.user?.id};ctx.openDrawer(`<p class="asset-delete-summary">删除「${esc(x.title)}」${x.kind!=='file'?' · '+esc(amount(x)):''}？</p><p class="section-desc">记录将放入最近删除，30 天内可以恢复。</p>`,'删除'+kindName(x.kind),'仅删除当前工作台中的这条记录',`${btn('取消','close')}${btn('确认删除','asset-confirm-delete:'+id,'primary')}`);}
 function upload(){const sourceSpace=ctx.space,sourceWorkbench=ctx.workbench,owner=ctx.account?.user?.id;ctx.openDrawer(`<form id="asset-upload-form">${field('资料名称（选填）','title','','text','maxlength="120"')}${field('资料日期','date',ctx.today,'date','required')}<label class="asset-file-picker">${icon('file',25)}<span>选择账单或证明原件</span><input name="file" type="file" accept=".pdf,.png,.jpg,.jpeg,.webp,.txt" required><small>PDF、图片、TXT · 单份最大10MB</small></label><div class="field"><label for="asset-upload-note">备注与来源</label><textarea id="asset-upload-note" name="note" maxlength="5000"></textarea></div><div id="asset-upload-error" role="alert"></div></form>`,'上传资产资料','文件保存在当前资产空间，不会自动改动余额',`${btn('取消','close')}<button class="btn primary" form="asset-upload-form" type="submit">上传原件</button>`);const form=document.querySelector('#asset-upload-form');form.onsubmit=async e=>{e.preventDefault();if(ctx.space!==sourceSpace||ctx.workbench!==sourceWorkbench||ctx.account?.user?.id!==owner){ctx.toast('空间或账号已变化，请重新打开表单');return;}const button=document.querySelector('[form="asset-upload-form"]');button.disabled=true;try{const file=form.elements.file.files[0];if(!file||file.size>10*1024*1024)throw Error('请选择不超过10MB的文件');const content=await new Promise((r,j)=>{const reader=new FileReader();reader.onload=()=>r(String(reader.result).split(',')[1]);reader.onerror=()=>j(Error('文件读取失败'));reader.readAsDataURL(file)});await ctx.api('/api/upload',{method:'POST',body:JSON.stringify({name:file.name,title:form.elements.title.value||file.name,date:form.elements.date.value,note:form.elements.note.value,content})},sourceSpace,sourceWorkbench);if(form.isConnected)ctx.closeDrawer();await ctx.load();ctx.toast('资产资料已保存');}catch(error){if(form.isConnected)document.querySelector('#asset-upload-error').innerHTML=`<div class="form-error">${esc(error.message)}</div>`;}finally{button.disabled=false;}};}
 async function handle(action,id){if(action==='asset-add')edit(id);else if(action==='asset-edit'){const x=find(id);if(x)edit(x.kind,id);}else if(action==='asset-detail')detail(id);else if(action==='asset-delete')remove(id);else if(action==='asset-confirm-delete'){const p=pendingDelete;if(!p||p.id!==id||p.space!==ctx.space||p.workbench!==ctx.workbench||p.owner!==ctx.account?.user?.id){ctx.toast('空间已变化，请重新操作');return;}await ctx.api('/api/items/'+id,{method:'DELETE'},p.space,p.workbench);ctx.closeDrawer();await ctx.load();ctx.toast('已移入最近删除');pendingDelete=null;}else if(action==='asset-preview'){const f=find(id);if(f?.kind==='file')await ctx.previews.open(f);}else if(action==='asset-upload')upload();}
