function workbenchTheme(value,type='health'){const color=/^#[0-9a-f]{6}$/i.test(value||'')?value:(type==='finance'?'#A65343':'#2C6B51');const rgb=[1,3,5].map(i=>parseInt(color.slice(i,i+2),16));const mix=(weight)=>'#'+rgb.map(v=>Math.round(v*(1-weight)+255*weight).toString(16).padStart(2,'0')).join('');const light=rgb.reduce((n,v,i)=>n+[.2126,.7152,.0722][i]*(v/255<=.04045?v/255/12.92:((v/255+.055)/1.055)**2.4),0);return {'--theme-accent':color,'--theme-soft':mix(.92),'--theme-border':mix(.72),'--theme-ink':light>.15?'#30332F':color,'--theme-on-accent':light>.179?'#000000':'#FFFFFF','--green':light>.15?'#30332F':color};}

