 if(action.startsWith('qc-')){await quick.handle(action,arg,el);return;}
 if(action.startsWith('cgm-')){await cgm.handle(action,arg,el);return;}
 if(action.startsWith('med-')){await medical.handle(action,arg,el);return;}
 if(action==='nav')navigate(arg);
 else if(action==='add'){if(arg==='choose')openDrawer(`<div class="helper">${space==='demo'?'示例空间':'个人空间'} · 选择你想留下的记录</div><div class="type-picker">${Object.entries(names).map(([k,l])=>`<button class="type-option" data-action="add:${k}"><span class="event-icon ${k}">${icon(k,22)}</span><strong>${l}</strong><small>${({visit:'就诊、检查与复查',exercise:'运动与身体感受',meal:'餐食与饮食备注',metric:'测量数值与睡眠',task:'安排下一件小事',file:'保存报告与资料'})[k]}</small></button>`).join('')}</div>`,'添加一份健康记录','连接你的健康日常');else if(['meal','exercise','metric','file'].includes(arg))quick.open(arg,arg==='metric'?{type:metricType}:{});else openForm(arg);}
 else if(action==='edit'){const x=items.find(x=>x.id===arg);if(x.kind==='water'){await daily.handle('daily-water-edit',arg,el);return;}if(['meal','exercise'].includes(x.kind)){quick.open(x.kind,x);return;}if(['medication','report','dose'].includes(x.kind))medical.openMedical(x.kind,arg);else openForm(x.kind,arg)}
 else if(action==='close')requestClose();
 else if(action==='personal'){await setSpace('personal');toast('已进入个人空间')}
 else if(action==='trend'){metricType=arg;render()}
 else if(action==='toggle'){const x=items.find(x=>x.id===arg);await api('/api/items/'+arg,{method:'PUT',body:JSON.stringify({done:!x.done})});await load();toast(x.done?'已取消完成':'计划已完成，给自己一点肯定')}
 else if(action==='delete'){const x=items.find(x=>x.id===arg);openDrawer(`<p class="section-desc">确定移除「${esc(x.title)}」？移除后 12 秒内可以撤销，之后 30 天内可在「我的 → 最近删除」恢复。${x.kind==='visit'?'关联附件会保留在资料档案中。':''}</p>`,'移除记录',space==='demo'?'示例空间':'个人空间',`${btn('取消','close')}${btn('确认移除','confirm-delete:'+arg,'danger','trash')}`)}
 else if(action==='confirm-delete'){const targetSpace=space,targetWorkbench=workbench,targetName=workbenches.find(w=>w.id===workbench)?.name||'原工作台',dialog=$('.drawer');const r=await api('/api/items/'+arg,{method:'DELETE'},targetSpace,targetWorkbench);undo={space:targetSpace,workbench:targetWorkbench,name:targetName,record:r.deleted};if(dialog?.isConnected)closeDrawer();await load();toast(`已从${targetName}工作台移除记录`,`撤销${targetName}记录`,'undo')}
 else if(action==='undo'){if(!undo)throw Error('撤销已失效');const target=undo;undo=null;await api('/api/restore',{method:'POST',body:JSON.stringify(target.record)},target.space,target.workbench);await load();toast(`记录已恢复到${target.name||'原'}工作台`)}
 else if(action==='trash-open')await openTrash();
 else if(action==='trash-restore')await restoreTrash(arg);
 else if(action==='trash-restore-with'){await restoreTrash(arg,true);if(!$('#trash-list'))await openTrash();}
 else if(action==='trash-view'){const x=lastRestored;if(!x)return;closeDrawer();if(x.workbench&&x.workbench!==workbench)await switchWorkbench(x.workbench);navigate(trashRoute(x));}
 else if(action==='assistant')assistant();
