async function setSpace(next){shell.assets.cleanup();cgm.cleanup();previews.cleanupAll();space=next==='personal'?'personal':'demo';localStorage.setItem('health-space',space);query='';filterDate='';filterStatus='all';undo=null;closeDrawer();items=[];loadSequence++;const cached=stateCache.get(cacheKey(space,workbench));refreshFailure=null;if(cached){shownState=cacheKey(space,workbench)+'\n'+JSON.stringify(cached.data);items=cached.data.items;trashedIds=cached.data.trashedIds||[];settings=cached.data.settings;today=cached.data.today;workbenches=cached.data.workbenches||workbenches;render();await load({retainOnError:true});}else{shownState=null;renderSwitchSkeleton();await load();}}
async function switchWorkbench(id){shell.assets.cleanup();cgm.cleanup();previews.cleanupAll();if(!workbenches.some(w=>w.id===id)){toast('工作台不存在');return;}const routes=JSON.parse(localStorage.getItem('workbench-routes')||'{}');routes[workbench]=route;localStorage.setItem('workbench-routes',JSON.stringify(routes));closeDrawer();workbench=id;localStorage.setItem('active-workbench',id);items=[];settings={name:'Captain',focus:''};query='';filterDate='';filterStatus='all';undo=null;$('#toast').style.display='none';loadSequence++;route=routes[id]||'dashboard';page=route.split('/')[0];location.hash=route;const cached=stateCache.get(cacheKey(space,workbench));refreshFailure=null;if(cached){/* stale-while-revalidate: any age */shownState=cacheKey(space,workbench)+'\n'+JSON.stringify(cached.data);items=cached.data.items;trashedIds=cached.data.trashedIds||[];settings=cached.data.settings;today=cached.data.today;render();await load({retainOnError:true});}else{shownState=null;renderSwitchSkeleton();await load();}}
