// Home skeleton shown the instant login succeeds, until the workbench renders.
const homeSkeleton=()=>'<div class="home-skeleton" role="status" aria-busy="true" aria-label="正在打开工作台"><div class="sk sk-title"></div><div class="sk sk-card"></div><div class="sk sk-row"></div><div class="sk sk-row"></div><div class="sk sk-row short"></div></div>';
const account=createAccount({openDrawer,closeDrawer,toast,onUnauthorized:()=>{shell.assets.cleanup();cgm.cleanup();previews.cleanupAll();closeDrawer();applicationReady=false;loadSequence++;invalidateStateCache();items=[];settings={};undo=null;},loginQuery:()=>'?space=personal&workbench=health',onAuthenticated:async(_user,result)=>{shell.assets.cleanup();cgm.cleanup();previews.cleanupAll();closeDrawer();applicationReady=false;invalidateStateCache();items=[];settings={};undo=null;loadSequence++;space='personal';workbench='health';route='dashboard';page='dashboard';workbenches=[{id:'health',name:'健康',type:'health'},{id:'finance',name:'资产',type:'finance'}];localStorage.setItem('health-space',space);localStorage.setItem('active-workbench',workbench);history.replaceState(null,'','#dashboard');$('#overlay').replaceChildren();$('#app').innerHTML=homeSkeleton();applicationReady=true;const state=result?.state;if(state&&result.me?.user?.id===account.user?.id&&state.space===space&&state.workbench?.id===workbench){loadSequence++;applyState(cacheKey(space,workbench),state);}else await load();}});
const shell=createShell({get items(){return items},get settings(){return settings},get space(){return space},get today(){return today},get page(){return page},get workbench(){return workbench},get workbenches(){return workbenches},get account(){return account},previews,api,load,render,navigate,setSpace,switchWorkbench,refreshRegistry:async created=>{if(!workbenches.some(x=>x.id===created.id))workbenches.push(created)},openDrawer,closeDrawer,toast,icon,esc,field,btn});
// One startup request (/api/bootstrap) replaces /api/auth/me + /api/state; any failure falls back to the old sequence.
let boot=null;try{const body=await api('/api/bootstrap',{timeoutMs:7000});if(body?.me)boot=body;}catch{}
if(await account.initialize(boot?.me)){applicationReady=true;if(account.enabled&&!localStorage.getItem('health-space'))space='personal';const state=boot?.state;if(state&&state.space===space&&state.workbench?.id===workbench){loadSequence++;applyState(cacheKey(space,workbench),state);}else await load();}
